import{_ as r,C as o,o as i,c as E,a2 as s,b as d,w as a,a as l,E as p,a3 as n}from"./chunks/framework.DIWxYxwh.js";const b=JSON.parse('{"title":"BERT 微调：短文本表情分类","description":"","frontmatter":{},"headers":[],"relativePath":"LLM训练/BERT微调.md","filePath":"LLM训练/BERT微调.md","lastUpdated":1791869861000}'),h={name:"LLM训练/BERT微调.md"};function k(B,t,c,u,g,A){const e=o("Mermaid");return i(),E("div",null,[t[3]||(t[3]=s(`<h1 id="bert-微调-短文本表情分类" tabindex="-1">BERT 微调：短文本表情分类 <a class="header-anchor" href="#bert-微调-短文本表情分类" aria-label="Permalink to &quot;BERT 微调：短文本表情分类&quot;">​</a></h1><p>BERT 适合将短文本映射到预先定义的固定类别。对于表情分类，可以在预训练编码器上增加一个分类头，通过交叉熵损失训练模型，使其根据句子语义预测对应类别。</p><p>与生成式模型相比，BERT 分类模型结构更简单，输出类别固定，推理时不需要生成自然语言回答，适合类别明确、响应速度要求较高的分类任务。</p><p>下面以中文短回复的八类表情分类为例：<strong>害怕、生气、疑惑、愉悦、无、悲伤、害羞、惊喜</strong>。更换类别时，应同步调整标注口径、标签映射、数据集和评测指标。</p><h2 id="一、先统一标注口径" tabindex="-1">一、先统一标注口径 <a class="header-anchor" href="#一、先统一标注口径" aria-label="Permalink to &quot;一、先统一标注口径&quot;">​</a></h2><p>标注目标是判断说话人此刻适合呈现的表情，而不是根据句子中出现的情绪词直接分类。同一个词在不同语境下可能对应不同类别。</p><table tabindex="0"><thead><tr><th>类别</th><th>标注范围</th><th>不应归入的情况</th></tr></thead><tbody><tr><td>害怕</td><td>惊吓、恐惧、危险，以及上台或见人前的发怵</td><td>运维式「先暂停操作」；单纯害羞时的紧张</td></tr><tr><td>生气</td><td>指责、发火、被冒犯、带有愤怒的威胁或警告</td><td>单纯翻白眼、阴阳怪气、不耐烦</td></tr><tr><td>疑惑</td><td>没听懂、逻辑矛盾、明显困惑或无法理解</td><td>语气平静的事务询问</td></tr><tr><td>愉悦</td><td>开心、友好寒暄、满足，以及邀约时的高兴</td><td>意外带来的惊喜；被夸后的羞赧</td></tr><tr><td>无</td><td>通知、指引、安抚、出糗后的尴尬、嘲讽或不耐烦</td><td>明显的喜怒哀惧</td></tr><tr><td>悲伤</td><td>失落、想念、难过、心疼自己或他人</td><td>惊吓；主要表现为愤怒的生闷气</td></tr><tr><td>害羞</td><td>被注视、被夸、表白或初见时的羞赧</td><td>纯粹开心；纯粹害怕</td></tr><tr><td>惊喜</td><td>意料之外的好消息、惊讶和意外发现</td><td>计划内的高兴；由危险引起的惊吓</td></tr></tbody></table><p>「无」并不代表文本没有情绪，而是指在当前八分类口径下，不需要表达其他七类表情。</p><p>「无」内部可以继续记录四种子型，用于错误分析：</p><ul><li><strong>通知：</strong> 会议室在三楼。</li><li><strong>安抚：</strong> 别想太多。</li><li><strong>尴尬：</strong> 发错群了。</li><li><strong>嘲讽：</strong> 行了吧、又画大饼。</li></ul><p>这些子型仅用于分析，模型最终仍输出八类之一。生气与嘲讽的边界是：明确发火、指责或威胁归生气；主要表现为阴阳怪气、不耐烦或讥讽，且没有明显愤怒时归无。</p><h3 id="容易混淆的句子" tabindex="-1">容易混淆的句子 <a class="header-anchor" href="#容易混淆的句子" aria-label="Permalink to &quot;容易混淆的句子&quot;">​</a></h3><ul><li>「好紧张」：上台或面对危险时归害怕；被喜欢的人注视时归害羞。</li><li>「你怎么能这样，我真的很伤心」：归悲伤。</li><li>「这个功能怎么用」：平静请教归无；明显困惑、无法理解时归疑惑。</li><li>「居然」「没想到」「哇」：意外本身归惊喜；计划内的高兴归愉悦；受到惊吓归害怕；没听懂归疑惑。</li><li>「他不在了」「群里突然安静了」：只有在语境明确表达失落或想念时才归悲伤，不能仅凭「不在」「安静」等词判断。</li><li>「夜里」「门口」等场景词不直接决定类别，应根据整句话的含义标注。</li></ul><h3 id="固定标签映射" tabindex="-1">固定标签映射 <a class="header-anchor" href="#固定标签映射" aria-label="Permalink to &quot;固定标签映射&quot;">​</a></h3><p>类别顺序必须在配置文件、标签表和数据集中保持一致。建议使用稳定的英文 ID 存储标签，展示时再映射为中文名称。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">labels </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;afraid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;angry&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;confused&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;happy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;neutral&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;sad&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;shy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;surprised&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>训练开始前，应校验标签表、数据标签和模型输出维度是否一致；不一致时停止训练。增删类别时，应同步更新标签映射、数据集、分类头和冻结评测集。</p><h2 id="二、数据构建与清洗" tabindex="-1">二、数据构建与清洗 <a class="header-anchor" href="#二、数据构建与清洗" aria-label="Permalink to &quot;二、数据构建与清洗&quot;">​</a></h2>`,18)),(i(),d(n,null,{default:a(()=>[p(e,{id:"mermaid-202",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%E5%B7%B2%E6%9C%89%E8%AF%AD%E6%96%99%22%5D%20--%3E%20C%5B%22%E6%8C%89%E6%A0%87%E6%B3%A8%E5%8F%A3%E5%BE%84%E6%B8%85%E6%B4%97%22%5D%0A%20%20%20%20B%5B%22%E6%B7%B7%E6%B7%86%E7%B1%BB%E5%9C%BA%E6%99%AF%E8%A1%A5%E5%8F%A5%22%5D%20--%3E%20C%0A%20%20%20%20C%20--%3E%20D%5B%22%E5%8E%BB%E9%87%8D%E5%B9%B6%E5%A4%84%E7%90%86%E5%86%B2%E7%AA%81%E6%A0%87%E7%AD%BE%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E6%8E%92%E9%99%A4%E5%86%BB%E7%BB%93%E8%AF%84%E6%B5%8B%E9%9B%86%E5%8F%8A%E8%BF%91%E9%87%8D%E5%A4%8D%E6%A0%B7%E6%9C%AC%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%E8%AE%AD%E7%BB%83%E9%9B%86%E3%80%81%E9%AA%8C%E8%AF%81%E9%9B%86%E3%80%81%E6%B5%8B%E8%AF%95%E9%9B%86%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=s(`<p>从已有语料出发，先按照统一口径清理错误标签。例如，「先暂停操作」「先确认风险」表达的是操作步骤，不应仅因包含「风险」就标为害怕。</p><p>清洗后，只针对仍然容易混淆的类别补充真实场景句，例如害怕、害羞和无。不需要为了让每个类别数量相等而机械扩充；应根据类别分布、混淆矩阵和实际使用场景补充数据。</p><h3 id="数据格式与去重" tabindex="-1">数据格式与去重 <a class="header-anchor" href="#数据格式与去重" aria-label="Permalink to &quot;数据格式与去重&quot;">​</a></h3><p>每条样本包含文本和类别 ID，例如：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;这个功能怎么用？&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;label&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;neutral&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;居然真的成功了！&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;label&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;surprised&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>读入时应：</p><ul><li>删除空文本、未知标签和不符合任务要求的异常样本。</li><li>根据任务定义设置最短文本长度；短于两个字的文本应先检查是否有实际分类价值，而不是一律认定无效。</li><li>同一句话出现多次且标签一致时，保留一条或按明确的采样策略处理。</li><li>同一句话存在冲突标签时，优先人工复核；无法确认的样本应排除，避免监督信号相互矛盾。</li></ul><h3 id="训练集与评测集划分" tabindex="-1">训练集与评测集划分 <a class="header-anchor" href="#训练集与评测集划分" aria-label="Permalink to &quot;训练集与评测集划分&quot;">​</a></h3><p>应事先冻结手工评测集，并在合成训练数据时排除其中的原文及近重复改写，防止相同句子同时出现在训练集和评测集中。</p><p>对于已有语料，可以使用分层抽样，以约 8:1:1 的比例划分训练集、验证集和测试集，并固定随机种子。该比例只是起点，应根据数据量和类别分布调整。</p><p>三份数据的用途不同：</p><ul><li><strong>训练集：</strong> 更新模型参数。</li><li><strong>验证集：</strong> 选择模型、调整超参数和阈值。</li><li><strong>测试集：</strong> 在模型配置确定后进行最终评估。</li><li><strong>冻结手工评测集：</strong> 检查真实场景和易混淆边界上的表现，用于不同实验之间的稳定对比。</li></ul><p>冻结手工集应与训练数据隔离，且不应反复用于调参。如果根据手工集的错误不断补句或改规则，应另建开发集，保留原手工集用于独立评估。</p><p>随机测试集表现很好、手工集表现明显较差，通常说明数据分布或场景覆盖存在差异，也可能存在近重复样本或训练集过于简单的问题。此时不能只依据随机测试集判断上线效果。</p><h2 id="三、模型结构" tabindex="-1">三、模型结构 <a class="header-anchor" href="#三、模型结构" aria-label="Permalink to &quot;三、模型结构&quot;">​</a></h2>`,15)),(i(),d(n,null,{default:a(()=>[p(e,{id:"mermaid-284",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20T%5B%22%E7%9F%AD%E6%96%87%E6%9C%AC%22%5D%20--%3E%20K%5B%22Tokenizer%20%E5%88%86%E8%AF%8D%22%5D%0A%20%20%20%20K%20--%3E%20Enc%5B%22BERT%20%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%0A%20%20%20%20Enc%20--%3E%20CLS%5B%22CLS%20%E9%9A%90%E7%8A%B6%E6%80%81%E6%88%96%20Pooler%20%E8%BE%93%E5%87%BA%22%5D%0A%20%20%20%20CLS%20--%3E%20Drop%5B%22Dropout%22%5D%0A%20%20%20%20Drop%20--%3E%20Head%5B%22Linear%20%E5%88%86%E7%B1%BB%E5%A4%B4%22%5D%0A%20%20%20%20Head%20--%3E%20Logits%5B%228%20%E7%BB%B4%20logits%22%5D%0A"})]),fallback:a(()=>[...t[1]||(t[1]=[l(" Loading... ",-1)])]),_:1})),t[5]||(t[5]=s('<p>以常见的中文 BERT-base 为例，模型通常包含 12 层 Transformer 编码器，隐藏维度为 768，参数规模约为 1 亿。具体结构应从所用预训练模型的配置读取，不应假定所有 BERT 模型规格一致。</p><p>输入文本经过 tokenizer 转换为 token ID，并按照配置进行补齐或截断。编码器输出隐藏状态后，可以采用以下两种常见表示：</p><ul><li><strong>Pooler 输出：</strong> 使用模型提供的池化结果；具体定义取决于预训练模型的实现和训练方式。</li><li><strong><code>[CLS]</code> 隐状态：</strong> 直接取最后一层第一个 token 的隐藏向量。</li></ul><p>两者并不相同，应根据基座模型结构和验证结果选择，并在训练与推理中保持一致。</p><p>分类头通常为 Dropout 加线性层，输出八个 logits：</p><p>$$ \\mathbf{z} = W\\mathbf{h} + \\mathbf{b} $$</p><p>其中，$\\mathbf{h}$ 为句子表示，$W$ 和 $\\mathbf{b}$ 为分类头的权重和偏置，$\\mathbf{z}$ 为八类未归一化分数。</p><p>分类头可以采用标准差为 0.02 的正态分布初始化权重，并将偏置初始化为 0。具体初始化策略应与训练框架配置一致。</p><p>训练时直接将 logits 输入交叉熵损失，不需要提前执行 softmax：</p><p>$$ \\mathcal{L} = -\\log p_y $$</p><p>其中，$p_y$ 表示模型对真实类别的预测概率；标准交叉熵内部会完成相应的归一化计算。</p><p>推理时才根据需要执行 softmax、选择最大概率类别，并应用经过验证集校准的置信度阈值。</p><h3 id="冻结训练与全参数微调" tabindex="-1">冻结训练与全参数微调 <a class="header-anchor" href="#冻结训练与全参数微调" aria-label="Permalink to &quot;冻结训练与全参数微调&quot;">​</a></h3><p>数据较少时，可以先冻结 BERT 编码器，只训练分类头，用于验证数据和标签是否具备一定的可分性。但冻结训练效果不佳，不一定代表标签错误，也可能是预训练表示不足以区分当前类别。</p><p>当数据量和标注质量足够时，可以解冻编码器进行全参数微调。BERT-base 分类任务的学习率可从 <code>2e-5</code> 附近尝试，具体仍需通过验证集确定。</p><p>如果先冻结编码器训练分类头，再继续训练，则需要显式解冻编码器，并重新检查优化器是否包含解冻后的参数。</p><p>隐藏维度、层数和 tokenizer 都应从基座配置读取。更换骨干模型后，需要重新训练分类头，并验证分词、最大序列长度和推理输入格式。</p><p>当模型效果不佳时，应先检查标注口径、训练数据分布和类别混淆，再考虑更换骨干、加入上下文或调整网络结构。</p><h2 id="四、训练参数与模型选择" tabindex="-1">四、训练参数与模型选择 <a class="header-anchor" href="#四、训练参数与模型选择" aria-label="Permalink to &quot;四、训练参数与模型选择&quot;">​</a></h2><p>超参数、数据路径、标签映射、阈值和随机种子应集中管理。对比实验尽量只调整少数参数，并保持其他条件一致。</p><p>以下参数适合作为一组初始实验配置，不代表所有数据集上的最优设置。</p><table tabindex="0"><thead><tr><th>参数</th><th>初始设置</th><th>作用与注意事项</th></tr></thead><tbody><tr><td>学习率</td><td><code>2e-5</code></td><td>全参数微调的常见起点；过大可能破坏预训练表示</td></tr><tr><td><code>batch_size</code></td><td>16</td><td>每批样本数；受显存、序列长度和模型大小限制</td></tr><tr><td><code>num_train_epochs</code></td><td>上限 10</td><td>最大训练轮数，实际通常由早停决定</td></tr><tr><td><code>warmup_ratio</code></td><td>0.1</td><td>前 10% 的训练步数用于学习率预热</td></tr><tr><td>学习率调度器</td><td><code>linear</code></td><td>预热后按计划将学习率线性衰减至零</td></tr><tr><td><code>weight_decay</code></td><td>0.01</td><td>权重衰减，通常使用 AdamW</td></tr><tr><td><code>max_grad_norm</code></td><td>1.0</td><td>梯度裁剪阈值，限制梯度范数</td></tr><tr><td>早停耐心</td><td>3</td><td>验证集 Macro F1 连续 3 个评测轮次未改善时停止</td></tr><tr><td>标签平滑</td><td>0.1 或关闭</td><td>软化训练目标，是否启用应通过验证集判断</td></tr><tr><td>类别权重</td><td>默认关闭</td><td>类别明显不均衡时，可尝试按训练集频数设置权重</td></tr><tr><td><code>max_length</code></td><td>128</td><td>最大输入长度；根据文本分布统计和截断率确定</td></tr></tbody></table><h3 id="参数调整注意事项" tabindex="-1">参数调整注意事项 <a class="header-anchor" href="#参数调整注意事项" aria-label="Permalink to &quot;参数调整注意事项&quot;">​</a></h3><p><strong>学习率与训练步数：</strong> 每个 epoch 的更新步数取决于训练集大小、批次大小、梯度累积和分布式配置。修改 batch size 后，warmup 的实际步数和训练总步数也可能变化。</p><p><strong>标签平滑：</strong> 启用 <code>label_smoothing=0.1</code> 时，真实类别的目标概率会被降低，其余类别分配少量概率质量。它可能改善泛化，但也可能降低部分任务的分类效果，不能保证模型不会对错误预测给出高置信度。</p><p><strong>类别权重：</strong> 可以依据训练集类别频数调整各类损失权重，但应防止少数类权重过高而影响整体表现。是否使用，应根据类别分布和各类召回率判断。</p><p><strong>序列长度：</strong> <code>max_length=128</code> 对多数短回复可能足够，但应统计实际 token 长度及截断比例。训练与推理应采用一致的 tokenizer 和截断规则；若只是改变 padding 长度且模型支持动态长度，通常不需要因此重新训练，但改变分词器或输入处理方式可能影响结果。</p><h3 id="模型选择指标" tabindex="-1">模型选择指标 <a class="header-anchor" href="#模型选择指标" aria-label="Permalink to &quot;模型选择指标&quot;">​</a></h3><p>建议以验证集 <strong>Macro F1</strong> 选择最佳 checkpoint，同时记录准确率、各类别 Precision、Recall、F1 和混淆矩阵。</p><p>Macro F1 是各类别 F1 的算术平均：</p><p>$$ F1_{\\text{macro}} = \\frac{1}{C}\\sum_{i=1}^{C}F1_i $$</p><p>其中 $C=8$。当类别不均衡时，准确率可能被多数类主导，而 Macro F1 能更直观地反映各类别的整体表现。</p><p>早停应依据验证集指标执行，并在训练结束后加载最佳 checkpoint，再对测试集和冻结手工评测集分别评估。不要用训练集上的高准确率代替泛化能力判断。</p><h3 id="推理置信度阈值" tabindex="-1">推理置信度阈值 <a class="header-anchor" href="#推理置信度阈值" aria-label="Permalink to &quot;推理置信度阈值&quot;">​</a></h3><p>推理时可根据 softmax 最大概率设置阈值：</p><p>$$ \\hat{p} = \\max_i \\operatorname{softmax}(\\mathbf{z})_i $$</p><p>若 $\\hat{p}$ 低于阈值，可以将结果标记为低置信度，交由人工复核或采用业务定义的兜底策略。</p><p>不建议直接认定低置信度样本都属于「无」，因为「无」是一个真实的表情类别，不等于模型不确定。若业务必须输出八类之一，可以在校准后采用兜底策略，但应单独评估其误判率。</p><p>阈值应通过独立验证数据选择。softmax 概率高不代表预测一定正确，因此不能仅凭一个固定阈值判断模型是否可靠。</p><h2 id="五、一个训练-step-在做什么" tabindex="-1">五、一个训练 step 在做什么 <a class="header-anchor" href="#五、一个训练-step-在做什么" aria-label="Permalink to &quot;五、一个训练 step 在做什么&quot;">​</a></h2>',40)),(i(),d(n,null,{default:a(()=>[p(e,{id:"mermaid-549",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%E4%B8%80%E6%89%B9%E5%8F%A5%E5%AD%90%E4%B8%8E%E6%A0%87%E7%AD%BE%22%5D%20--%3E%20B%5B%22BERT%20%E7%BC%96%E7%A0%81%E5%99%A8%E4%B8%8E%E5%88%86%E7%B1%BB%E5%A4%B4%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E8%AE%A1%E7%AE%97%20logits%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E4%BA%A4%E5%8F%89%E7%86%B5%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E5%8F%8D%E5%90%91%E4%BC%A0%E6%92%AD%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%E6%A2%AF%E5%BA%A6%E8%A3%81%E5%89%AA%22%5D%0A%20%20%20%20F%20--%3E%20G%5B%22AdamW%20%E6%9B%B4%E6%96%B0%E5%8F%82%E6%95%B0%22%5D%0A%20%20%20%20G%20--%3E%20H%5B%22%E6%8C%89%20step%20%E6%9B%B4%E6%96%B0%E5%AD%A6%E4%B9%A0%E7%8E%87%22%5D%0A"})]),fallback:a(()=>[...t[2]||(t[2]=[l(" Loading... ",-1)])]),_:1})),t[6]||(t[6]=s('<p>一个训练 step 通常包括前向计算、损失计算、反向传播、梯度裁剪和优化器更新。使用梯度累积时，多个微批次的梯度会累积后再执行一次参数更新。</p><p>训练模式下启用 Dropout 并计算梯度；验证模式下应切换到 <code>eval()</code>，关闭 Dropout，并使用 <code>no_grad()</code> 或 <code>inference_mode()</code> 停止梯度计算。</p><p>训练集准确率逐渐接近满分，说明模型越来越能拟合训练样本，但不能证明它已经学会真实场景中的表情边界。</p><p>每轮训练后，应在验证集上计算 Macro F1 和混淆矩阵。只有当验证指标超过历史最佳时，才更新最佳 checkpoint；必要时另存每轮权重，分析模型从哪一轮开始过拟合。</p><p>训练完成后，加载最佳 checkpoint，在固定测试集上生成分类报告，并单独评估冻结手工集。两类结果应分开记录，因为它们衡量的场景不同。</p><h2 id="六、迭代闭环" tabindex="-1">六、迭代闭环 <a class="header-anchor" href="#六、迭代闭环" aria-label="Permalink to &quot;六、迭代闭环&quot;">​</a></h2><p>一轮迭代包含以下步骤：</p><ol><li>分析验证集和手工评测集中的错误，确认问题来自标注、数据覆盖还是模型。</li><li>修订标注规则，或针对混淆类别补充真实场景句。</li><li>重新清洗、去重和划分数据，确保冻结评测集原文及近重复样本不进入训练集。</li><li>在相同配置和固定随机种子下训练，并根据验证集 Macro F1 选择模型。</li><li>在同一份冻结评测集上比较不同实验，记录各类别指标、混淆矩阵和错误案例。</li></ol><p>每次修改应尽量聚焦一个主要因素，例如先修复害怕与害羞的边界，再调整学习率或标签平滑。这样才能判断效果变化究竟来自数据、标注口径还是训练配置。</p>',9))])}const m=r(h,[["render",k]]);export{b as __pageData,m as default};
